+// API keys and roles. Keys live in the data as `apiKeys` ({ key, name, role }).
+// A role includes everything the roles before it may do: `viewer` reads,
+// `cook` also does the kitchen's daily work, `manager` does everything.
+import { createHash, timingSafeEqual } from "node:crypto";
+import { AppError } from "../errors.js";
+
+/** Roles, least to most powerful. */
+export const ROLES = Object.freeze(["viewer", "cook", "manager"]);
+
+const digest = (text) => createHash("sha256").update(text).digest();
+
+/** The API key record for a key string; throws `unauthorized` when there is none. */
+export function authenticate(store, key) {
+  let found = null;
+  if (typeof key === "string" && key !== "") {
+    const given = digest(key);
+    for (const k of store.data.apiKeys ?? []) {
+      if (typeof k.key !== "string" || k.key === "") continue;
+      if (timingSafeEqual(digest(k.key), given)) found ??= k;
+    }
+  }
+  if (!found) throw new AppError("unauthorized");
+  return found;
+}
+
+/** Throws `forbidden` unless the key's role is at least `needed`. */
+export function authorize(apiKey, needed) {
+  const has = ROLES.indexOf(apiKey.role);
+  const wants = ROLES.indexOf(needed);
+  if (has < 0 || wants < 0 || has < wants) throw new AppError("forbidden", { role: needed });
+}
